startedAtUtc = DateString[{"ISODate", "T", "Time", "Z"}, TimeZone -> 0];
(* llm machine contract: transition table -> enumeration through eight events -> bounded result. *)
stages = {"source", "optimized", "validated", "shipped", "rejected"};
events = {"optimize", "validate", "ship", "reject"};
transition[stage_, event_] := Switch[{stage, event},
  {"source", "optimize"}, "optimized",
  {"optimized", "validate"}, "validated",
  {"validated", "ship"}, "shipped",
  {"source", "reject"} | {"optimized", "reject"} | {"validated", "reject"}, "rejected",
  _, "none"];
runTransitions[trace_] := Fold[transition, "source", trace];
maximumEvents = 8;
tracesByLength = Table[Tuples[events, length], {length, 0, maximumEvents}];
traces = Join @@ tracesByLength;
outcomes = runTransitions /@ traces;
shippingTraces = Pick[traces, outcomes, "shipped"];
expectedShipping = (# === {"optimize", "validate", "ship"} &) /@ traces;
actualShipping = (# === "shipped" &) /@ outcomes;
<|"executionIdentifier" -> executionIdentifier, "startedAtUtc" -> startedAtUtc,
  "claimIdentifier" -> "a968cd0f-8c5d-5953-906c-e40769388abd",
  "stages" -> stages, "events" -> events,
  "transitionTable" -> Table[transition[stage, event], {stage, stages}, {event, events}],
  "maximumEvents" -> maximumEvents, "tracesPerLength" -> (Length /@ tracesByLength),
  "traceCount" -> Length[traces], "outcomeCounts" -> Counts[outcomes],
  "shippingTraces" -> shippingTraces,
  "mismatchCount" -> Count[MapThread[SameQ, {actualShipping, expectedShipping}], False],
  "finishedAtUtc" -> DateString[{"ISODate", "T", "Time", "Z"}, TimeZone -> 0]|>

